/**
 * Relations emitter — manifest rendering (ADR-044, REL-1).
 *
 * Renders one `defineRelations()` over the generated schema barrel. Complete
 * file, `@generated` banner, deterministic order — re-running with the same
 * graph is byte-identical (charter I2).
 */

import { buildRelationGraph, type RelationGraph } from './build-graph';
import type {
	ColumnRef,
	RelationEdge,
	RelationsEmitContext,
	ScopeConfigLiteral,
} from './types';

export const RELATIONS_MANIFEST_FILE = 'relations.ts';

/** Vendored-mode default, which is also what `project init` and the tests use. */
export const DEFAULT_SCOPE_FILTERS_IMPORT = '@shared/base-classes/scope-filters';

/**
 * The constant a hop into `table` reads its scope from — derived from the TABLE
 * identifier, not the entity name, because the manifest already keys on tables
 * and those are unique by construction (`opportunityContacts` →
 * `OPPORTUNITY_CONTACTS_SCOPE`).
 */
export function scopeConstName(table: string): string {
	return `${table.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase()}_SCOPE`;
}

/** `{ tenantScoped: true, softDelete: true, userTracking: false, enforcement: 'strict' }`. */
function renderScopeLiteral(cfg: ScopeConfigLiteral): string {
	return (
		`{ tenantScoped: ${cfg.tenantScoped}, softDelete: ${cfg.softDelete}, ` +
		`userTracking: ${cfg.userTracking}, enforcement: '${cfg.enforcement}' }`
	);
}

const BANNER = `// @generated by @pattern-stack/codegen — do not edit.
// Run \`codegen entity new --all\` to regenerate.
//
// The v2 Drizzle relation graph (ADR-044), derived from the entity YAML:
// \`relationships:\` blocks and \`Junction\` pairings. Every relation carries an
// explicit \`from\`/\`to\`, which is why none of them needs an \`alias\` — Drizzle
// only consults \`alias\` when it has to infer a relation's columns from the
// reverse side. See docs/specs/REL-1.md.
`;

/** `r.accounts.id` / `r.contacts.id.through(r.opportunityContacts.contactId)`. */
function renderRef(ref: ColumnRef): string {
	const base = `r.${ref.table}.${ref.column}`;
	return ref.through ? `${base}.through(r.${ref.through.table}.${ref.through.column})` : base;
}

function renderEdge(edge: RelationEdge): string {
	const config = [
		`from: ${renderRef(edge.from)}`,
		`to: ${renderRef(edge.to)}`,
		...(edge.optional === undefined ? [] : [`optional: ${edge.optional}`]),
		// The hop predicate. `owner` names the RELATION so a throw (a scoped target
		// with no `tenant_id`, a missing boundary under `strict`) points at the
		// declaration that is wrong rather than at a table name.
		...(edge.targetScope === null
			? []
			: [
					`where: { RAW: (t) => hopScope(t, ${scopeConstName(edge.targetTable)}, ` +
						`'${edge.sourceTable}.${edge.key}') } `.trimEnd(),
				]),
	].join(', ');
	return `\t\t${edge.key}: r.${edge.cardinality}.${edge.targetTable}({ ${config} }),`;
}

/**
 * The scope constants the graph needs, name-sorted, one per SCOPED table.
 *
 * Each entity's config is emitted here AND as the repository's `behaviors` —
 * both derived from the same YAML declaration, which is what I1 asks for
 * ("derive from the declaration", not "emit exactly once"). Two readers of one
 * declaration cannot drift; two declarations can.
 */
function scopeConstants(graph: RelationGraph): string[] {
	const byName = new Map<string, ScopeConfigLiteral>();
	for (const { edges } of graph.tables) {
		for (const edge of edges) {
			if (edge.targetScope === null) continue;
			byName.set(scopeConstName(edge.targetTable), edge.targetScope);
		}
	}
	return [...byName.entries()]
		.sort((a, b) => a[0].localeCompare(b[0]))
		.map(([name, cfg]) => `const ${name}: ScopeConfig = ${renderScopeLiteral(cfg)};`);
}


/**
 * The two type helpers every generated repository hangs its typed `with` include
 * on (REL-2 §2.3, §4). Emitted here, once, because the base repository cannot
 * declare them: with `TRelations` and the relation key as naked type parameters,
 * `DBQueryConfig<…>['with']` is a TS2536 (REL-2 §2.1).
 *
 * `IncludeOf` reaches the `with` slot through a CONDITIONAL indexed access
 * because `DBQueryConfig` collapses to a `with`-less object for a table that has
 * no relations in this graph — an entity with no `relationships:` and no junction.
 * Without the conditional, such an entity's repository would not compile; with
 * it, the include surface is uniform and that entity simply accepts `{}`.
 */
const TYPE_HELPERS = `
/** This project's relation graph, as a type. */
export type Relations = typeof relations;

/** The include surface of one table — the keys a \`with\` may name. */
export type IncludeOf<TTable extends keyof Relations> =
\t'with' extends keyof DBQueryConfig<'one', Relations, Relations[TTable]>
\t\t? NonNullable<DBQueryConfig<'one', Relations, Relations[TTable]>['with']>
\t\t: Record<string, never>;

/** The row shape a given include tree resolves to, nested exactly as asked. */
export type ResultOf<
\tTTable extends keyof Relations,
\tTWith extends IncludeOf<TTable>,
> = BuildQueryResult<Relations, Relations[TTable], { with: TWith }>;
`;

/**
 * Render the manifest source for a graph.
 *
 * `schemaImport` is the module specifier of the generated schema barrel,
 * relative to the manifest's own directory (they are siblings, so `./schema`).
 */
export function buildRelationsManifest(
	graph: RelationGraph,
	schemaImport = './schema',
	scopeFiltersImport = DEFAULT_SCOPE_FILTERS_IMPORT,
): string {
	const constants = scopeConstants(graph);
	// A graph that declares no scope anywhere emits neither the import nor the
	// constants, so its manifest is byte-identical to what REL-1 emitted. Nothing
	// grows for consumers who do not scope.
	const scopeHead =
		constants.length === 0
			? ''
			: `import { hopScope, type ScopeConfig } from '${scopeFiltersImport}';\n`;
	const head =
		`${BANNER}import { defineRelations } from 'drizzle-orm';\n` +
		`import type { BuildQueryResult, DBQueryConfig } from 'drizzle-orm';\n\n` +
		`${scopeHead}import * as schema from '${schemaImport}';\n\n` +
		(constants.length === 0 ? '' : `${constants.join('\n')}\n\n`);

	if (graph.tables.length === 0) {
		// A project with no relations still exports a manifest: the emitted
		// `database.module.ts` imports it unconditionally, and `project init`
		// writes this shape before any entity exists.
		return `${head}export const relations = defineRelations(schema, () => ({}));\n${TYPE_HELPERS}`;
	}

	const body = graph.tables
		.map(({ table, edges }) => `\t${table}: {\n${edges.map(renderEdge).join('\n')}\n\t},`)
		.join('\n');

	return `${head}export const relations = defineRelations(schema, (r) => ({\n${body}\n}));\n${TYPE_HELPERS}`;
}

/** Convenience: context → source string. */
export function buildRelationsManifestFromContext(
	ctx: RelationsEmitContext,
	schemaImport = './schema',
): { content: string; warnings: string[] } {
	const graph = buildRelationGraph(ctx);
	return {
		content: buildRelationsManifest(
			graph,
			schemaImport,
			ctx.scopeFiltersImport ?? DEFAULT_SCOPE_FILTERS_IMPORT,
		),
		warnings: graph.warnings,
	};
}

/** The manifest a project with no entities gets (`project init`). */
export function emptyRelationsManifest(schemaImport = './schema'): string {
	return buildRelationsManifest({ tables: [], warnings: [] }, schemaImport);
}
